import pytest

from peptide import neutral_peptide_mass, residue_mass_sum, tryptic_digest


def test_residue_mass_sum_skadyek():
    assert residue_mass_sum("SKADYEK") == pytest.approx(821.392, abs=0.001)


def test_neutral_peptide_mass_skadyek():
    assert neutral_peptide_mass("SKADYEK") == pytest.approx(839.402, abs=0.001)


def test_tryptic_digest_mkrpgkaar():
    assert tryptic_digest("MKRPGKAAR") == ["MK", "RPGK", "AAR"]


@pytest.mark.parametrize(
    "seq",
    ["SKADYEK", "MKRPGKAAR", "", "K", "KP", "AAKRPPKRR", "PEPTIDE", "MKTAYIAKQRQISFVK"],
)
def test_digest_rejoin_roundtrip(seq):
    assert "".join(tryptic_digest(seq)) == seq

